import Fastify from 'fastify'
import fastifyApollo from '@as-integrations/fastify'
import cors from '@fastify/cors'
import multipart from '@fastify/multipart'
import swagger from '@fastify/swagger'
import swaggerUI from '@fastify/swagger-ui'
import { ApolloServer } from '@apollo/server'
import * as dotenv from 'dotenv-flow'
import * as fs from 'fs'
import * as path from 'path'
import * as swaggerJSDoc from 'swagger-jsdoc'
import * as mongoDB from './gen/services/db'
import { generateResolver, connectApi } from './gen/entry'
import { createUser, createRole, getAdminPasswordHash } from './gen/extras'
import { setupAuth } from './gen/api-auth'
import { createContext } from './gen/http-context'
import setupPassport from './services/passport'
import { registerStorageService, registerStorageRouter } from './gen/storage'
import { registerSendMailService } from './services/sendMail'

// Load configuration before creating services or authentication strategies.
dotenv.config({ path: './config/environment' })
const PORT = process.env.PORT || 3001
// Public file keys are 128 characters, longer than the router's default limit.
const app = Fastify({ routerOptions: { maxParamLength: 256 } })

app.setErrorHandler((error: any, request, reply) => {
    if (error.tokenExpired) return reply.code(200).send({ data: {}, errors: [error] })
    const status = error.status || error.statusCode || 500
    if (status >= 500) request.log.error(error)
    return reply.code(status).send({ errors: [{ name: error.name, message: error.message, status }] })
})
app.addHook('onSend', async (request, reply) => {
    reply.header('X-Response-Time', `${reply.elapsedTime}ms`)
})
app.register(cors, { origin: '*' })
app.register(multipart, { limits: { fileSize: 20 * 1024 * 1024, files: 10 } })

const { entry, resolvers } = generateResolver({})
const passport = setupAuth(app, entry.models['user'])
const publicPassportConfig = setupPassport(app, entry.models['user'], {
    GITHUB_CLIENT_ID: process.env.GITHUB_CLIENT_ID,
    GITHUB_CLIENT_SECRET: process.env.GITHUB_CLIENT_SECRET,
    GOOGLE_CLIENT_ID: process.env.GOOGLE_CLIENT_ID,
    GOOGLE_CLIENT_SECRET: process.env.GOOGLE_CLIENT_SECRET,
    FACEBOOK_APP_ID: process.env.FACEBOOK_APP_ID,
    FACEBOOK_APP_SECRET: process.env.FACEBOOK_APP_SECRET,
    SERVICE_URL: process.env.SERVICE_URL,
}, passport)
app.register(async (api) => { connectApi(api, entry) }, { prefix: '/api' })

const typeDefs = fs.readFileSync(path.join(__dirname, 'gen/graphql.schema'), 'utf8')
const apollo = new ApolloServer({ typeDefs, resolvers })

const swaggerSpec = swaggerJSDoc({
    definition: {
        openapi: '3.0.0',
        info: { title: 'REST API for Server', version: '1.0.0' },
        components: {
            securitySchemes: {
                bearerAuth: { type: 'http', scheme: 'bearer', bearerFormat: 'JWT' },
            },
        },
        security: [{ bearerAuth: [] }],
    },
    apis: [path.join(__dirname, 'gen/api/*.ts'), path.join(__dirname, 'gen/api-auth.ts')],
})
app.register(swagger, { mode: 'static', specification: { document: swaggerSpec } })
app.register(swaggerUI, { routePrefix: '/swagger' })

////////////////////////////////////////////////////////////////////////////////////////
// EMAIL
entry['email'] = registerSendMailService({
    SERVICE_NAME: process.env.SERVICE_NAME,
    REPLY_EMAIL: process.env.REPLY_EMAIL,
    SERVICE_URL: process.env.SERVICE_URL,
    EMAIL_WELLCOME_TITLE: process.env.EMAIL_WELLCOME_TITLE,
    EMAIL_WELLCOME_MESSAGE: process.env.EMAIL_WELLCOME_MESSAGE,
    EMAIL_FORGOTTEN_PASSWORD_TITLE: process.env.EMAIL_FORGOTTEN_PASSWORD_TITLE,
    EMAIL_FORGOTTEN_PASSWORD_MESSAGE: process.env.EMAIL_FORGOTTEN_PASSWORD_MESSAGE,
})

////////////////////////////////////////////////////////////////////////////////////////
// STORAGE
const storageTargetDir = process.env.STORAGE_DIR || './file-storage/'
if (!fs.existsSync(storageTargetDir)) {
    fs.mkdirSync(storageTargetDir, { recursive: true })
}

// TODO: please introduce better solution that with this entry
entry['storage'] = registerStorageService(entry.models['file'], storageTargetDir)

registerStorageRouter(entry, app, storageTargetDir)

app.get('/health', async () => ({
    health: 'ok',
    service: {
        SERVICE_NAME: process.env.SERVICE_NAME,
        SERVICE_URL: process.env.SERVICE_URL,
        REPLY_EMAIL: process.env.REPLY_EMAIL,
    },
    passport: publicPassportConfig,
}))

export async function updateAdminUser(passwordIsHashed = false) {
    const admin_email = process.env.ADMIN_EMAIL || `admin@graphql.monster`
    const admin_pass = process.env.ADMIN_PASSWORD || `admin@graphql.monster`

    const adminPasswordHash = await getAdminPasswordHash(admin_pass, passwordIsHashed)

    // TODO: add all roles what is in schema
    const adminRole = await createRole(entry, 'admin')
    const adminUser = await createUser(entry, admin_email, adminPasswordHash, [adminRole._id])
    return [adminUser, adminRole]
}

// One lifecycle closes listeners before Apollo and database connections.
app.addHook('onClose', async () => {
    await apollo.stop()
    await mongoDB.close()
})

export const connectionPromise = (async () => {
    try {
        await apollo.start()
        app.register(fastifyApollo(apollo), {
            context: async (request, reply) => createContext(request, reply),
        })
        await mongoDB.connect({
            host: process.env.DB_HOST,
            db: process.env.DB_NAME || 'db_graphql_monster',
        })
        await updateAdminUser()
        await app.listen({ port: Number(PORT), host: process.env.HOST || '0.0.0.0' })
        console.info(`listening on port: ${app.server.address()['port']} /graphql`)
        return { app, httpServer: app.server, mongoDB, apollo, entry }
    } catch (error) {
        await app.close()
        throw error
    }
})()

const shutdown = async () => {
    await app.close()
}
process.once('SIGINT', shutdown)
process.once('SIGTERM', shutdown)
app.addHook('onClose', async () => {
    process.removeListener('SIGINT', shutdown)
    process.removeListener('SIGTERM', shutdown)
})

export default app
